#!/usr/bin/env bash
# generate-codemap.sh — plan a regenerated CODEMAP.md with loom.
#
# CODEMAP.md used to be built here from each directory's README first line, which
# left a TODO for every directory without a README. It is now generated by loom
# from the import graph and the context index (ADR-010): entrypoints, highest
# fan-in, inferred layers and one-line purposes, with no placeholders.
#
# This script only plans the change. Like everything loom writes into a
# repository it goes through an approval gate, so nothing is written until you
# review and approve it:
#
#   bash scripts/generate-codemap.sh
#   loom docs approve      # review the summary, then confirm
#   loom docs apply
#
# Usage: bash scripts/generate-codemap.sh
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

if ! command -v loom >/dev/null 2>&1; then
  echo "generate-codemap.sh: the loom CLI is required (brew install orieken/tap/loom," >&2
  echo "or: go install github.com/orieken/loom/cmd/loom@latest)." >&2
  exit 1
fi

loom index --root "$REPO_DIR"
loom docs plan --root "$REPO_DIR" --codemap-only
